// Choose a valid directory path: prefer the parent directory of a fuzz-created file; fall back to CWD
const char *rand_file = FUZZ_PARAM_FILENAME();
std::filesystem::path dir = std::filesystem::path(rand_file).parent_path();
std::error_code ec{};
if (dir.empty() || !std::filesystem::is_directory(dir, ec)) {
  dir = std::filesystem::current_path();
}
// Construct a minimal, thread-safe callback. It must be callable as void(event const&)
// and be safe from a background thread.
auto events_seen = std::make_shared<std::atomic<int>>(0);
::wtr::watcher::event::callback cb = [events_seen](::wtr::watcher::event const &ev) noexcept {
  // Basic, non-throwing processing to exercise callback path; avoid blocking.
  (void)ev;
  events_seen->fetch_add(1, std::memory_order_relaxed);
};
// Start the asynchronous watch. This immediately launches a background task and
// invokes the callback with a watcher lifecycle event.
::wtr::watcher::watch *watch = new ::wtr::watcher::watch(dir, cb);
// Track lifecycle for downstream stubs. The watch remains alive until explicitly closed.
FUZZ_SET_ATTR_INT(watch, "closed", 0);
FUZZ_SET_ATTR_PTR(watch, "events_seen_ptr", static_cast<void *>(events_seen.get()));
// Validation: the object must be non-null and now owns the callback and its state.
FUZZ_ASSERT(watch != nullptr, "watch construction must return a valid object");

// Enforce that input is valid
FUZZ_ASSERT(watch != nullptr, "watch must be a valid pointer");
// First call should initiate shutdown and may block briefly until the background task completes.
bool ok = watch->close();
// Track and assert idempotent semantics: subsequent calls should return false.
int already_closed = FUZZ_GET_ATTR_INT(watch, "closed");
if (already_closed) {
  // If we have already observed a successful close, close() must now return false.
  FUZZ_ASSERT(!ok, "close() must return false after the first successful shutdown");
} else {
  // Record first successful close (best-effort; if ok==false, leave state as not-closed)
  if (ok) {
    FUZZ_SET_ATTR_INT(watch, "closed", 1);
  }
}
// Keep the object in the pool; it remains valid post-close though further close() should be false.
// Validation: object remains non-null and tracked as closed when ok was true.
